function getImageDimensions(dataUrl) {
  return new Promise((resolve) => {
    if (typeof window === "undefined") {
      resolve({
        width: 4,
        height: 3,
      });
      return;
    }
    const img = new Image();
    img.onload = () => {
      resolve({
        width: img.naturalWidth || img.width || 4,
        height: img.naturalHeight || img.height || 3,
      });
    };
    img.onerror = () => {
      resolve({
        width: 4,
        height: 3,
      });
    };
    img.src = dataUrl;
  });
}
